import React from 'react';
import { NavLink } from 'react-router-dom';
import {
  FiHome,
  FiCalendar,
  FiImage,
  FiVideo,
  FiBriefcase,
  FiBook,
  FiMessageSquare,
  FiSettings,
} from 'react-icons/fi';

const AdminSidebar = () => {
  const menuItems = [
    { path: '/', label: 'Dashboard', icon: FiHome },
    { path: '/events', label: 'Events', icon: FiCalendar },
    { path: '/gallery', label: 'Gallery', icon: FiImage },
    { path: '/videos', label: 'Videos', icon: FiVideo },
    { path: '/services', label: 'Services', icon: FiBriefcase },
    { path: '/courses', label: 'Courses', icon: FiBook },
    { path: '/messages', label: 'Messages', icon: FiMessageSquare },
    { path: '/settings', label: 'Settings', icon: FiSettings },
  ];

  return (
    <aside className="fixed left-0 top-16 bottom-0 w-64 bg-blue-900 text-white shadow-lg overflow-y-auto">
      <nav className="p-4">
        <div className="space-y-1">
          {menuItems.map((item) => (
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) =>
                `flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
                  isActive
                    ? 'bg-yellow-400 text-blue-900'
                    : 'hover:bg-blue-800 text-gray-300 hover:text-white'
                }`
              }
            >
              <item.icon className="text-xl" />
              <span className="font-medium">{item.label}</span>
            </NavLink>
          ))}
        </div>
      </nav>
    </aside>
  );
};

export default AdminSidebar;
